package com.nbi.dto.model;

import java.math.BigDecimal;

// The ENTITY: internal, holds sensitive + internal fields. NEVER returned directly.
public class Account {
    private String id;
    private String holderName;
    private String passwordHash;    // secret
    private int internalRiskScore;  // internal only
    private BigDecimal balance;
    private BigDecimal pendingHolds;

    public Account(String id, String holderName, String passwordHash,
                   int internalRiskScore, BigDecimal balance, BigDecimal pendingHolds) {
        this.id = id; this.holderName = holderName; this.passwordHash = passwordHash;
        this.internalRiskScore = internalRiskScore; this.balance = balance;
        this.pendingHolds = pendingHolds;
    }
    public String getId() { return id; }
    public String getHolderName() { return holderName; }
    public String getPasswordHash() { return passwordHash; }
    public int getInternalRiskScore() { return internalRiskScore; }
    public BigDecimal getBalance() { return balance; }
    public BigDecimal getPendingHolds() { return pendingHolds; }
}
```

