package com.nbi.dto.dto;

import jakarta.validation.constraints.*;
import java.math.BigDecimal;

// REQUEST DTO: what a client may SEND. Carries a password + validation.
// Note: NO isAdmin / riskScore field → prevents mass-assignment attacks.
public record CreateAccountRequest(
        @NotBlank String holderName,
        @NotBlank @Size(min = 8) String password,
        @NotNull @DecimalMin("0.00") BigDecimal openingBalance) {}
