// ─── File: src/main/java/com/nbi/dto/service/AccountService.java ───
package com.nbi.dto.service;

import com.nbi.dto.dto.*;
import com.nbi.dto.model.Account;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class AccountService {
    private final Map<String, Account> store = new HashMap<>();

    public AccountService() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar",
                "hash$2a$abc", 42, new BigDecimal("1000000.00"), new BigDecimal("50000.00")));
    }

    public AccountResponse create(CreateAccountRequest r) {
        String id = "ACC-" + UUID.randomUUID().toString().substring(0, 6);
        // Server sets internal fields; client CANNOT inject risk score.
        Account a = new Account(id, r.holderName(), hash(r.password()),
                0, r.openingBalance(), BigDecimal.ZERO);
        store.put(id, a);
        return toResponse(a);
    }

    public Optional<AccountResponse> find(String id) {
        return Optional.ofNullable(store.get(id)).map(this::toResponse);
    }

    // Mapping lives HERE in the service layer, not the controller.
    private AccountResponse toResponse(Account a) {
        BigDecimal available = a.getBalance().subtract(a.getPendingHolds()); // computed
        return new AccountResponse(a.getId(), a.getHolderName(), a.getBalance(), available);
        // passwordHash and internalRiskScore are simply NOT copied → never leak.
    }

    private String hash(String raw) { return "hash$" + Integer.toHexString(raw.hashCode()); }
}
```

