// ─── File: src/main/java/com/nbi/dto/controller/AccountController.java ───
package com.nbi.dto.controller;

import com.nbi.dto.dto.*;
import com.nbi.dto.service.AccountService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.net.URI;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    // Controller is a thin adapter: it only receives DTOs and returns DTOs.
    @PostMapping
    public ResponseEntity<AccountResponse> create(@Valid @RequestBody CreateAccountRequest r) {
        AccountResponse resp = service.create(r);
        return ResponseEntity.created(URI.create("/api/v1/accounts/" + resp.accountId())).body(resp);
    }

    @GetMapping("/{id}")
    public ResponseEntity<AccountResponse> get(@PathVariable String id) {
        return service.find(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());
    }
}
